ALTER TABLE "semesters" DROP CONSTRAINT "semesters_valid_period_targets";--> statement-breakpoint
ALTER TABLE "semesters" ADD CONSTRAINT "semesters_complete_period_targets" CHECK (("semesters"."weekly_target_hours" is null and "semesters"."monthly_target_hours" is null and "semesters"."target_basis" is null) or ("semesters"."weekly_target_hours" is not null and "semesters"."monthly_target_hours" is not null and "semesters"."target_basis" is not null and "semesters"."weekly_target_hours" > 0 and "semesters"."weekly_target_hours" <= 84 and "semesters"."monthly_target_hours" > 0 and "semesters"."monthly_target_hours" <= 372 and "semesters"."target_basis" in ('WEEKLY', 'MONTHLY')));